<?php
function req(string $key):string{$v=getenv($key);if($v===false||$v==='')throw new RuntimeException('QA_CONFIG: missing '.$key);return $v;}
try{
 $database=req('QA_DB_DATABASE');if($database!=='gimnasia_unificada_test')throw new RuntimeException('QA_CONFIG: wrong database');
 $mysql=new PDO('mysql:host='.req('QA_DB_HOST').';port='.req('QA_DB_PORT').';dbname='.$database.';charset=utf8mb4',req('QA_DB_USER'),getenv('QA_DB_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $info=$mysql->query('SELECT DATABASE() AS db, VERSION() AS version, @@sql_mode AS sql_mode, @@character_set_database AS charset, @@collation_database AS collation')->fetch(PDO::FETCH_ASSOC);if($info['db']!==$database)throw new RuntimeException('Wrong DB');
 $tables=$mysql->query("SELECT TABLE_NAME AS table_name, ENGINE AS engine FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('usuarios','roles','postulaciones','solicitudes_nivel','evaluaciones_juez')")->fetchAll(PDO::FETCH_ASSOC);
 $columns=$mysql->query("SELECT COLUMN_NAME AS name,COLUMN_TYPE AS type,IS_NULLABLE AS nullable FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='postulaciones' ORDER BY ORDINAL_POSITION")->fetchAll(PDO::FETCH_ASSOC);
 $foreignKeys=(int)$mysql->query('SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL')->fetchColumn();
 $users=[];foreach(['ADMIN'=>'Administrador','JUDGE'=>'Juez','ATHLETE'=>'Gimnasta','GUEST'=>'Invitado'] as $role=>$expected){$email=getenv('QA_'.$role.'_EMAIL');if(!$email){$users[$role]=['configured'=>false];continue;}$q=$mysql->prepare('SELECT u.ID_Usuario AS id,u.activo AS active,r.NombreRol AS role FROM usuarios u JOIN roles r ON r.ID_Rol=u.ID_Rol WHERE u.Email=?');$q->execute([$email]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$row=$rows[0]??null;$users[$role]=['configured'=>true,'unique'=>count($rows)===1,'actualId'=>$row?(int)$row['id']:null,'active'=>$row?(bool)$row['active']:false,'roleMatches'=>$row&&$row['role']===$expected,'idMatches'=>(string)($row['id']??'')===(string)getenv('QA_'.$role.'_ID')];}
 $sqlite=new PDO('sqlite::memory:');$sqlite->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$defaultFk=(int)$sqlite->query('PRAGMA foreign_keys')->fetchColumn();$sqlite->exec('PRAGMA foreign_keys=ON');
 $mysql->exec('CREATE TEMPORARY TABLE qa_type_probe (v VARCHAR(2), n DECIMAL(5,2))');$sqlite->exec('CREATE TABLE qa_type_probe (v VARCHAR(2), n DECIMAL(5,2))');
 $probe=function(PDO $db):array{$out=[];try{$db->exec("INSERT INTO qa_type_probe VALUES ('abcdef',1.239)");$out['long_varchar']='accepted';}catch(PDOException $e){$out['long_varchar']='rejected';$out['sqlstate']=$e->getCode();}$db->exec("INSERT INTO qa_type_probe VALUES ('ok',1.239)");$out['decimal']=$db->query("SELECT n FROM qa_type_probe WHERE v='ok'")->fetchColumn();$out['case_insensitive_matches']=(int)$db->query("SELECT COUNT(*) FROM qa_type_probe WHERE v='OK'")->fetchColumn();return $out;};
 echo json_encode(['checkedAt'=>gmdate('c'),'database'=>$info,'tables'=>$tables,'foreignKeyCount'=>$foreignKeys,'qaUsers'=>$users,'postulacionesColumns'=>$columns,'mysqlProbe'=>$probe($mysql),'sqlite'=>['version'=>$sqlite->query('SELECT sqlite_version()')->fetchColumn(),'defaultForeignKeys'=>$defaultFk,'probeForeignKeys'=>(int)$sqlite->query('PRAGMA foreign_keys')->fetchColumn(),'probe'=>$probe($sqlite)],'scope'=>'Read-only metadata and schema; only MySQL temporary table and SQLite memory were written. No migrations or persistent table changes.'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
}catch(Throwable $e){fwrite(STDERR,'QA_DATABASE_AUDIT_FAILED: '.get_class($e).' / code '.$e->getCode().PHP_EOL);exit(2);}
